import pefile, re
from capstone import *
pe = pefile.PE("mix_oracle.exe")
img = pe.get_memory_mapped_image()
md = Cs(CS_ARCH_X86, CS_MODE_64)
hits={}
for ins in md.disasm(img[0x1000:0x1000+0x15430], 0x140001000):
    if 'rip' in ins.op_str:
        m=re.search(r'\[rip ([+-]) (0x[0-9a-f]+)\]', ins.op_str)
        if m:
            off=int(m.group(2),16)*(1 if m.group(1)=='+' else -1)
            rva=(ins.address+ins.size+off)-0x140000000
            if 0x22000<=rva<0x23c20:
                hits.setdefault(rva,[]).append((ins.address-0x140000000, ins.mnemonic, ins.op_str))
for rva in sorted(hits):
    for a,mn,ops in hits[rva]:
        print(hex(rva), hex(a), mn, ops)
